import type { ImageRef, LensView } from "./types";

/**
 * Built-in content of the Services lens' "shared world" image system. TEMPORARY CALIBRATION ARTWORK (public/media/services-world/, generated by
 * scripts/gen-services-world-assets.mjs): a numbered overview with seven regions and one matching detail image per service. It is not client work
 * and must be replaced by the final overview and service images in the dashboard (Services showcase). Used as the default content and as the fallback for
 * older saved content that has no shared-world data, so the lens is never blank.
 */
const dir = "/media/services-world";
export const CALIBRATION_OVERVIEW: ImageRef = { src: `${dir}/overview.webp`, alt: "", width: 2400, height: 2400 };

const view = (n: number, x: number, y: number, zoom: number): LensView => ({
  target: { x, y },
  zoom,
  focal: { x: 0.5, y: 0.5 },
  image: { src: `${dir}/service-${n}.webp`, alt: "", width: 1200, height: 1200 },
});

/** Per service id: target on the overview (0–1 of the image), arrival zoom, focal point of the dedicated image, and the dedicated image. */
export const CALIBRATION_VIEWS: Record<string, LensView> = {
  branding: view(1, 0.5, 0.2, 4.0),
  "creative-strategy": view(2, 0.76, 0.35, 4.4),
  "content-production": view(3, 0.76, 0.65, 3.8),
  "social-media": view(4, 0.5, 0.8, 4.2),
  design: view(5, 0.24, 0.65, 4.0),
  "paid-media": view(6, 0.24, 0.35, 4.6),
  "web-experiences": view(7, 0.5, 0.5, 3.6),
};
/** Where a service with no saved view of its own points (centre, 3×): keeps the lens working for a service added later. */
export const FALLBACK_VIEW: LensView = { target: { x: 0.5, y: 0.5 }, zoom: 3, focal: { x: 0.5, y: 0.5 }, image: null };

export const WORLD_ZOOM = { min: 1.5, max: 6 } as const;
